export const BODY: string = "\n<p>تطبيق مرشح صورة يستغرق بضع دقائق فقط. ترفع الصورة وتختار نمطًا وتثبت الشدة وتنزّل النسخة المنمقة.</p>\n<p>هذا البرنامج التعليمي يمر بالعملية كاملة خطوة بخطوة. يغطي شبكة المرشحات ومنزلق الشدة وأدوات المقارنة وضبط التصدير التي تبقي النتيجة بمظهر نظيف.</p>\n<p>في النهاية ستستطيع تنسيق صورة شخصية أو مشهد أو صورة طعام بمظهر متسق على أي جهاز. واحتفظ بالصورة الأصلية حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: اختر المزاج</h2>\n<p>قرر أي مزاج تريد قبل فتح الأداة. جو دافئ وحنين يناسب Vintage أو Sepia، بينما جو درامي يناسب أبيض وأسود Noir أو درامي.</p>\n<p>فكر في أين ستعيش الصورة: خلاصة اجتماعية تحتاج مظهرًا متسقًا، بينما طبعة واحدة تحتاج فقط المرشح الذي يناسب تلك الصورة. واستخدم الصورة الأصلية، لا نسخة مضغوطة: مرشح مطبق على أصل حاد يبدو نظيفًا، بينما مرشح مطبق على نسخة ناعمة يبدو خشنًا.</p>\n<p>افتح <a href=\"/ar/murashshahat-as-suwar/\">أداة مرشحات الصور</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">طبّق مرشح صورة في خمس خطوات</h2>\n<p>العملية نفسها لكل نمط مرشح. ارفع الصورة وتصفح الشبكة وثبت الشدة وقارن ونزّل.</p>\n<p>خذ وقتك مع الشدة. قيمة أقل غالبًا تبدو أفضل من القوة الكاملة، والمعاينة تُظهر لك بالضبط متى يبدو التأثير جيدًا. وافتح الملف المنزّل مرة قبل مشاركته، وتأكد من أن المرشح يبدو جيدًا وأن الموضوع ما زال يُرى بوضوح.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>تصفح شبكة المرشحات واضغط نمطًا، مثل Vintage أو دافئ أو Sepia أو أبيض وأسود Noir، لتراه على صورتك.</li>\n<li>اسحب منزلق شدة المرشح لتثبيت القوة، من 0 بالمئة للأصل إلى 100 بالمئة للتأثير الكامل.</li>\n<li>استخدم اضغط للعرض لرؤية الأصل أو المقارنة المقسومة لمراجعة النسخة المرشحة مقابل الأصل.</li>\n<li>اختر صيغة التصدير والجودة، ثم اضغط تنزيل لحفظ الصورة المرشحة.</li>\n</ol>\n<h2 id=\"browsing-filter-grid\">كيف تتصفح شبكة المرشحات</h2>\n<p>تُظهر شبكة المرشحات مصغرة حية لصورتك تحت كل نمط من الأنماط الـ11. تتحدث المصغرات بصورتك الحقيقية، فتستطيع رؤية ما يفعله كل مرشح قبل الضغط عليه.</p>\n<p>تصفح الشبكة ببطء وراقب المصغرات: المرشح الصحيح غالبًا يبرز فورًا، لأنه يطابق مزاج الصورة. واضغط مربعًا لتطبيق ذلك المرشح على اللوحة الرئيسية: المعاينة الكبيرة تُظهر التأثير الكامل، وهو أسهل حكمًا من المصغرة الصغيرة.</p>\n<p>إذا لم يبرز أي مرشح، جرّب Vintage أولًا. إنه الافتراضي لسبب: مظهره الناعم الباهت يناسب معظم الصور ونادرًا ما يجعل صورة تبدو أسوأ.</p>\n<h2 id=\"setting-intensity\">كيف تثبت شدة المرشح</h2>\n<p>تتراوح الشدة من 0 إلى 100 بالمئة. عند 100 بالمئة يُعرض المرشح الكامل، بينما عند 0 بالمئة لا تتغير الصورة.</p>\n<p>تثبيت الشدة دون 100 بالمئة يمزج البكسلات المرشحة عودة نحو الأصل. مرشح Vintage بـ45 بالمئة يعطي غسل فيلم خفيف دون إخفات نغمات البشرة. وجرّب المرشح عند 100 بالمئة أولًا لرؤية طابعه، ثم اخفض الشدة حتى يبدو التأثير جيدًا: المعاينة تتحدث حيًا، فتستطيع إيجاد النقطة الصحيحة.</p>\n<p>للصور الشخصية، شدة أقل 40 إلى 60 بالمئة غالبًا أفضل: تضيف مزاجًا دون تغيير الوجه، وهذا ما تحتاجه صورة شخصية.</p>\n<h2 id=\"comparing-with-original\">كيف تقارن مع الأصل</h2>\n<p>استخدم اضغط للعرض لرؤية الأصل لمراجعة سريعة: اضغط مطولًا لرؤية الصورة دون مرشح، وأفلت لرؤية النسخة المرشحة، والفرق يقفز إلى العين فورًا.</p>\n<p>استخدم المقارنة المقسومة لمراجعة دقيقة: تُظهر الأصل والنسخة المرشحة جنبًا إلى جنب، لتستطيع رؤية أي مناطق تغيرت بالضبط. وراجع البشرة والسماء والظلال في المقارنة: مرشح يبدو جيدًا في الخلفية قد يجعل الوجه برتقاليًا أو السماء بيضاء.</p>\n<p>إذا بدت النسخة المرشحة أسوأ من الأصل، جرّب مرشحًا آخر أو اخفض الشدة: مرشح يجب أن يحسّن الصورة، لا أن يغيّرها فقط.</p>\n<h2 id=\"using-vintage\">كيف تستخدم مرشح Vintage</h2>\n<p>Vintage هو المرشح الافتراضي، المختار عند 100 بالمئة عند رفع صورة. ألوانه الباهتة وتباينه الناعم تعطي مظهر فيلم حنين خفيف.</p>\n<p>جرّب Vintage عند 50 بالمئة لتأثير ألطف: يبقى المظهر الباهت، لكن الصورة تحتفظ بمزيد من لونها الطبيعي، ما يناسب الصور الشخصية واللقطات اليومية. ويناسب Vintage الصور العفوية والمنشورات الاجتماعية والذكريات: يبدو دافئًا ومألوفًا، ولهذا هو أشهر مرشح في المجموعة.</p>\n<p>إذا بدا Vintage باهتًا جدًا، جرّب دافئ أو ساعة ذهبية: المرشحات الدافئة الثلاثة تشترك في مزاج لكنها تختلف في النغمة، فأحدها غالبًا يناسب.</p>\n<h2 id=\"using-black-white\">كيف تستخدم رمادي وأبيض وأسود Noir</h2>\n<p>رمادي يزيل اللون ويترك صورة أبيض وأسود نظيفة. يناسب العمارة وتصوير الشارع وأي صورة يكون فيها الشكل أهم من اللون.</p>\n<p>أبيض وأسود Noir يزيل اللون ويضيف تباينًا قويًا: يتعمق الأسود ويفتّح الأبيض، وتكتسب الصورة صفة درامية سينمائية. واستخدم رمادي عندما يجب أن تبدو الصورة هادئة ووثائقية، واستخدم أبيض وأسود Noir عندما يجب أن تبدو درامية، بظلال قوية وأضواء حادة.</p>\n<p>بعد التحويل إلى أبيض وأسود، راجع التباين: صورة رمادية غالبًا تحتاج دفعة تباين صغيرة، لأن اللون كان يحمل جزءًا من العمق.</p>\n<h2 id=\"using-warm-cool\">كيف تستخدم المرشحين الدافئ والبارد</h2>\n<p>دافئ يضيف صبغة ذهبية تبدو مشمسة ومريحة. يناسب الصور الشخصية والطعام والمشاهد، حيث توهج دافئ يجعل الصورة تبدو دافئة.</p>\n<p>بارد يضيف صبغة زرقاء تبدو هادئة وحادة. يناسب مشاهد الشتاء والعمارة ومنتجات التقنية، حيث لوحة باردة تبدو حديثة ونظيفة. وجرّب الاثنين على نفس الصورة وقارن: الفرق يقفز إلى العين فورًا، والصحيح غالبًا يبدو كأنه ينتمي إلى المشهد.</p>\n<p>ولصورة التُقطت بضوء دافئ، مرشح دافئ يعزز التوهج الطبيعي. ولصورة التُقطت بضوء بارد، مرشح بارد يفعل الشيء نفسه.</p>\n<h2 id=\"filters-for-portraits\">مرشحات للصور الشخصية</h2>\n<p>الصور الشخصية تناسبها مرشحات ناعمة بشدة معتدلة. Vintage ودافئ وباهت غير لامع بـ40 إلى 60 بالمئة تضيف مزاجًا دون تغيير الوجه.</p>\n<p>تجنب تباين عالٍ ودرامي في الصور الشخصية، إلا إذا طلب المزاج ذلك: الظلال القوية قد تشيّخ الوجه وتجعل البشرة تبدو قاسية. وأبيض وأسود Noir يناسب الصور الشخصية ذات التعابير القوية: الأبيض والأسود الدرامي يؤكد العينين والعاطفة، ولهذا هو مرشح صور شخصية كلاسيكي.</p>\n<p>راجع نغمات البشرة بعد كل مرشح: مرشح يبدو جيدًا في الخلفية قد يجعل الوجه برتقاليًا أو أخضر أو رماديًا، فراجع الشخص أولًا دائمًا.</p>\n<h2 id=\"filters-for-food\">مرشحات لصور الطعام</h2>\n<p>صور الطعام تناسبها مرشحا دافئ وساعة ذهبية، اللذان يعززان الألوان الغنية والشهية. توهج دافئ يجعل الأطباق تبدو طازجة وجذابة.</p>\n<p>استخدم شدة معتدلة 40 إلى 60 بالمئة للطعام: مرشح بقوة كاملة قد يجعل الألوان تبدو اصطناعية، بينما مرشح ناعم يعززها بطبيعية. وتجنب بارد في صور الطعام: صبغة زرقاء تجعل الأطباق تبدو باردة وغير شهية، وهو عكس ما يجب أن تفعله صورة طعام.</p>\n<p>راجع الأحمر بعد الترشيح: الطماطم واللحم والتوت قد تصبح حمراء ساطعة غير طبيعية مع مرشح قوي، ما يجعل الطعام يبدو أقل شهية.</p>\n<h2 id=\"previewing\">المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل. تحقق من أن المرشح يبدو جيدًا، وأن الموضوع ما زال يُرى بوضوح، وأن نغمات البشرة طبيعية.</p>\n<p>استخدم زر اضغط للعرض لمقارنة سريعة مع الأصل: مرشح يبدو جيدًا وحده قد يبدو سيئًا بجانب الأصل، والمقارنة بالضغط تُظهر ذلك فورًا. وقرّب على البشرة والسماء والظلال بالحجم الكامل: هذه المناطق تُظهر مشاكل المرشح أولًا، وقد تخفي معاينة صغيرة المشكلة.</p>\n<p>إذا بدا المرشح قويًا جدًا، اخفض الشدة 10 بالمئة وراجع مجددًا: التخفيضات الصغيرة غالبًا تستعيد المظهر الطبيعي دون فقدان المزاج.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر JPG للصور التي تنوي مشاركتها. يبقي الملفات صغيرة ويعمل في كل مكان، وضبط جودة عالية يبقي الصورة المرشحة نظيفة.</p>\n<p>اختر PNG للرسوم والشعارات ذات الشفافية: لا يفقد PNG شيئًا، فتبقى الألوان دقيقة، ويحافظ على المناطق شبه الشفافة. واختر WebP عندما تريد ملفات صغيرة بجودة جيدة: يعمل جيدًا لصور الويب، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>تذكر أن ضبط الجودة يُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره. هذا سلوك طبيعي، لا مشكلة في الأداة.</p>\n<h2 id=\"applying-on-mobile\">كيف تطبق مرشحات على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع ترشيح صورة على الهاتف نفسه الذي التقطها. ارفع الصورة من معرضك والمس مربع مرشح ونزّل النتيجة.</p>\n<p>شبكة المرشحات سهلة التصفح على الهاتف: المس المصغرات وراقب كيف تتحدث المعاينة الرئيسية، ثم ثبت الشدة بالمنزلق. وراجع المعاينة بالحجم الكامل قبل التنزيل: مرشح يبدو جيدًا على شاشة هاتف صغيرة قد يكون قويًا جدًا عند رؤيته على حاسوب.</p>\n<p>تُحفظ الملفات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركة الصورة المرشحة مباشرة إلى تطبيق محادثة أو بريد أو منشور اجتماعي.</p>\n<h2 id=\"troubleshooting\">كيف تحل مشاكل المرشحات الشائعة</h2>\n<p>إذا بدا المرشح قويًا جدًا، اخفض الشدة: مرشح Vintage عند 100 بالمئة قد يطغى على الصورة، بينما نفس المرشح عند 50 بالمئة يضيف مزاجًا دون إخفاء الموضوع.</p>\n<p>وإذا بدت البشرة برتقالية أو خضراء، فالمرشح لا يناسب الصورة الشخصية: جرّب مرشحًا أنعم، مثل Vintage أو باهت غير لامع، أو اخفض الشدة. وإذا بدت الصورة أسوأ من الأصل، اضغط إعادة ضبط للعودة إلى الصورة دون مرشح: مرشح يجب أن يحسّن الصورة، لا أن يغيّرها فقط.</p>\n<p>وإذا بدا التنزيل مختلفًا عن المعاينة، راجع صيغة التصدير والجودة: ضبط جودة JPG منخفض قد يغيّر الألوان قليلًا، خصوصًا في المناطق الفاتحة.</p>\n<h2 id=\"consistent-feed\">كيف تبني خلاصة متسقة بالمرشحات</h2>\n<p>اختر مرشحًا وشدة، واستخدمهما لسلسلة كاملة: خلاصة تشترك كل صورة فيها في نفس Vintage عند 50 بالمئة تبدو معتنى بها، بينما المرشحات المختلطة تبدو عشوائية.</p>\n<p>اختبر المرشح على أنواع صور مختلفة قبل الالتزام: مرشح يناسب المشاهد قد لا يناسب الصور الشخصية، ومظهر متسق يحتاج مرشحًا يعمل في الاثنين. ودوّن مرشحك وشدته: ملاحظة قصيرة، مثل Vintage 50 بالمئة، تتيح لك إعادة إنتاج نفس المظهر في كل صورة تنشرها.</p>\n<p>راجع اختيار مرشحك من حين لآخر: الأنماط تتغير، ومرشح بدا جديدًا العام الماضي قد يبدو قديمًا الآن، فحدّثه عندما يتطور عملك.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لمرشحات أفضل</h2>\n<p>ابدأ بشدة كاملة لرؤية طابع المرشح، ثم اخفضها حتى يبدو التأثير جيدًا: شدة أقل غالبًا تبدو أفضل من التأثير الكامل.</p>\n<p>راجع البشرة والسماء والظلال بعد كل مرشح: هذه المناطق تُظهر المشاكل أولًا، وقد تخفي معاينة صغيرة المشكلة. واستخدم مرشحًا واحدًا لكل صورة: تكديس مرشحات بإعادة رفع الصورة المرشحة يضيف ضررًا مع كل جولة، ومرشح واحد مختار جيدًا أنظف.</p>\n<p>احفظ الصورة الأصلية دون مرشح. بمجرد أن يُدمج مرشح في تصدير، لا يمكن إزالته من ذلك الملف.</p>\n<h2 id=\"filter-for-wedding-photo\">كيف تطبق مرشحًا على صورة زفاف</h2>\n<p>صور الزفاف تناسبها مرشحات ناعمة. Vintage أو باهت غير لامع بـ40 إلى 50 بالمئة يضيفان جوًا ناعمًا ورومانسيًا دون تغيير الوجوه أو الفستان الأبيض.</p>\n<p>تجنب المرشحات القوية في صور الزفاف: تباين عالٍ ودرامي قد يشيّخ الزوجين ويجعل الفستان يبدو رماديًا، وهو عكس ما يحتاجه ألبوم زفاف. وراجع الفستان الأبيض بعد الترشيح: مرشح يصبغ الفستان بالأصفر أو الوردي يبدو سيئًا في ألبوم، فاخفض الشدة إن تغير لون الفستان.</p>\n<p>استخدم نفس المرشح لمجموعة الزفاف كلها: ألبوم تشترك كل صورة فيه في نفس المرشح الناعم يبدو احترافيًا، بينما المرشحات المختلطة تجعل اليوم يبدو مفككًا.</p>\n<p>للمقارنة، اقرأ <a href=\"/ar/blog/murashshahat-as-suwar-muqaranah/\">مرشحات الصور مقارنة: كيف تختار مظهرًا متسقًا</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-murashshahat-as-suwar/\">دليل مرشحات الصور الكامل</a>، ولضبط الألوان بدقة استخدم <a href=\"/ar/taadil-tashabbu-as-sura/\">محرر تشبع الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أطبق مرشحًا على صورة على هاتفي؟","answer":"افتح أداة مرشحات الصور في متصفح هاتفك وارفع الصورة من معرضك والمس مربع مرشح في الشبكة. واسحب منزلق الشدة لتثبيت القوة، واستخدم اضغط للعرض لمقارنتها مع الأصل ثم نزّل النتيجة."},{"question":"أي شدة يجب أن أستخدم لمرشح صورة شخصية؟","answer":"شدة معتدلة 40 إلى 60 بالمئة غالبًا تعمل أفضل للصور الشخصية: تضيف مزاجًا دون تغيير الوجه. والشدة الكاملة قد تجعل البشرة تبدو غير طبيعية، فابدأ عند 100 بالمئة لرؤية الطابع ثم اخفضها."},{"question":"أي مرشح أفضل لمشهد غروب؟","answer":"ساعة ذهبية أو دافئ، اللذان يعززان الضوء الدافئ الطبيعي للمشهد. ساعة ذهبية تحاكي ضوء الغروب مباشرة، بينما دافئ يضيف صبغة ذهبية. واستخدم شدة معتدلة ليحتفظ السماء بتدرجها."},{"question":"هل يمكنني رؤية كل المرشحات على صورتي قبل الاختيار؟","answer":"نعم، تُظهر شبكة المرشحات مصغرة حية لصورتك الحقيقية تحت كل نمط من الأنماط الـ11، فتستطيع رؤية ما يفعله كل مرشح قبل الضغط عليه. والمس مربعًا لتطبيقه على اللوحة الرئيسية للمعاينة الكاملة."},{"question":"لماذا تبدو صورتي المرشحة مختلفة بعد التنزيل؟","answer":"صيغة التصدير وضبط الجودة قد يغيّران الألوان قليلًا، خصوصًا مع جودة JPG منخفضة. وأعد التصدير بضبط جودة أعلى، أو بدّل إلى PNG لأدق الألوان. وقارن التنزيل بالمعاينة قبل المشاركة."},{"question":"هل يجب أن أستخدم نفس المرشح لكل صوري؟","answer":"لخلاصة اجتماعية أو سلسلة، نعم: مرشح وشدة واحد يبنيان نمطًا مميزًا. ولصور منفردة، اختر المرشح الذي يناسب كل صورة. واختبر مرشحك المختار على صور شخصية ومشاهد قبل الالتزام به."}];
